851→}
852→
853→/* Font size text buttons */
854→.sd-readbar__btn--font-down {
855→  font-family: var(--sd-font-sans);
856→  font-size: 10px;
857→  font-weight: 700;
858→}
859→
860→.sd-readbar__btn--font-up {
861→  font-family: var(--sd-font-sans);
862→  font-size: 14px;
863→  font-weight: 700;
864→}
865→
866→/* ── Font Size Overrides ───────────────────────────────────────── */
867→
868→.sd-messages[data-font="s"] .sd-message {
869→  font-size: 12px;
870→}
871→
872→.sd-messages[data-font="s"] .sd-text-body {
